// Little's Law: L = lambda * W  (in-flight = arrival_rate * time_in_system)
// Service: mean latency W = 0.020 s (20 ms) of pure service time per request.
const W = 0.020;            // seconds of service time per request
const lambda = 4000;        // target arrival rate, requests/second

// 1) Required concurrency to serve lambda at latency W:
const L = lambda * W;       // = 80 in-flight requests
console.log('required concurrency L = ' + L);

// 2) A pool/loop caps concurrency at C. Max sustainable throughput = C / W.
const C = 64;               // hard concurrency cap (e.g. pool size)
const maxRps = C / W;       // = 3200 req/s ceiling
console.log('max throughput at C=' + C + ' is ' + maxRps + ' rps');

// 3) Load curve: offered load below the ceiling is served; above it, requests
//    queue. Effective throughput plateaus at maxRps; the surplus only inflates W.
function curve(offered) {
  const served = Math.min(offered, maxRps);          // throughput plateaus
  const queueDepth = Math.max(0, offered - maxRps);  // backlog grows per second
  // time-in-system rises once we are over capacity (service + queue wait)
  const w = offered <= maxRps ? W : W + (queueDepth / maxRps) * W;
  return { offered, served, wMs: +(w * 1000).toFixed(1), overKnee: offered > maxRps };
}
for (const off of [1600, 3200, 3600, 4000]) {
  const r = curve(off);
  console.log('offered=' + r.offered + ' served=' + r.served + ' W=' + r.wMs + 'ms' + (r.overKnee ? ' [PAST KNEE: latency climbs, throughput flat]' : ''));
}
